// TrueTime API (conceptual)
TT.now()    → TTInterval { earliest: T - ε, latest: T + ε }
TT.after(t) → bool   // true only if real time has definitely passed t
TT.before(t)→ bool   // true only if real time has definitely not reached t

// Commit-wait: pick s = TT.now().latest, then wait until TT.after(s)
// Guarantees any future TT.now().earliest > s on any node worldwide
// Typical wait ≈ 2ε ≈ 14 ms

