Percolator commit flow (simplified, 2 rows: A and B):

ts_start = oracle.get_timestamp()   // e.g. 100

// Phase 1 — Prewrite
row A: CAS lock=nil → lock='primary'; data@100 = new_val_A
row B: CAS lock=nil → lock='secondary→A'; data@100 = new_val_B

// Phase 2 — Commit (atomic on primary row only)
ts_commit = oracle.get_timestamp()  // e.g. 105
row A: CAS lock='primary' → write@105 = data_ptr; lock=nil

// Secondary lock cleanup (lazy, by next reader or async)
row B: write@105 = data_ptr; lock=nil

// Any reader at ts >= 105 sees new_val_A and new_val_B atomically

